// Project-scoped review records for the interactive prototype.
const projectReviews={},projectHistory={};
let reviewPersona='PM';
function reviews(){return projectReviews[selected] ||= {configKey:'',client:false,technical:false,pm:false,comments:{}};}
function reviewSnapshot(route){return JSON.stringify({stage:route,requirements:backlog().rows,srs:typeof sectionDrafts!=='undefined'?sectionDrafts[selected]:null,baseline:current().approved,configuration:timelineState(),timeline:generatedTimelines[selected]||null,architecture:architectureState(),tests:Object.fromEntries(Object.entries(requirementTestCases).filter(([k])=>k.startsWith(selected+':'))),reviews:reviews()});}
function captureProjectVersion(route,reason='Saved changes'){const key=selected+':'+route,list=projectHistory[key] ||= [],data=reviewSnapshot(route);if(list.at(-1)?.data!==data)list.push({data,author:profile.name,time:new Date().toISOString(),reason});}
function showProjectHistory(route){captureReq();captureProjectVersion(route);const list=projectHistory[selected+':'+route]||[],box=document.getElementById('modal');box.className='history-dialog';box.innerHTML='<div class="history-heading"><div><h2>Version history</h2><p>'+esc(pageNames[route]||route)+'</p></div><button onclick="document.getElementById(\'modal\').close()" aria-label="Close">×</button></div><div class="history-body">'+list.slice().reverse().map((v,i)=>'<article class="history-card"><strong>Version '+(list.length-i)+'</strong><p>'+esc(v.author)+' · '+new Date(v.time).toLocaleString()+'</p><p>'+esc(v.reason)+'</p><details><summary>View snapshot</summary><pre>'+esc(JSON.stringify(JSON.parse(v.data),null,2))+'</pre></details></article>').join('')+'</div><div class="history-footer">Browser-session history · Read-only snapshots</div>';box.showModal();}
function personaControl(){return '<label class="review-persona">Preview as<select onchange="reviewPersona=this.value;render()">'+['Client','CTO','PM','Team Lead','Developer','Senior Engineer'].map(r=>'<option '+(r===reviewPersona?'selected':'')+'>'+r+'</option>').join('')+'</select></label><p class="sub">Simulated reviews in this browser session. Roles are not authenticated.</p>';}
function syncTeamConfig(){const els=[...document.querySelectorAll('#timelineInputs input')];if(els.length!==7)return false;for(const e of els)if(!e.value||!e.checkValidity()){e.reportValidity();return false;}const keys=['frontend','backend','qa','hours','days','buffer','start'];const t=Object.fromEntries(els.map((e,i)=>[keys[i],i===6?e.value:Number(e.value)]));if(t.frontend+t.backend+t.qa===0){toast('Add at least one team member.');return false;}timelineSettings[selected]=t;const r=reviews(),key=JSON.stringify(t);if(key!==r.configKey){r.configKey=key;r.client=false;r.technical=false;r.pm=false;backlog().approved=false;delete generatedTimelines[selected];}return true;}
function approveTeamConfig(kind){if(!syncTeamConfig())return;const allowed=kind==='client'?reviewPersona==='Client':['CTO','PM'].includes(reviewPersona);if(!allowed)return toast('Select the required reviewer in Preview as.');reviews()[kind]=true;captureProjectVersion('timeline',kind==='client'?'Client approved configuration':'CTO/PM approved configuration');render();}
const generateBeforeReview=generateTimelineResult;
generateTimelineResult=function(){if(!syncTeamConfig())return;if(!reviews().client||!reviews().technical)return toast('Client and CTO/PM approval are required before generating a timeline.');reviews().pm=false;return generateBeforeReview();};
const approveBeforeReview=approveDeliveryPlan;
approveDeliveryPlan=function(){if(reviewPersona!=='PM')return toast('PM approval is required. Select PM in Preview as.');if(!reviews().client||!reviews().technical||!generatedTimelines[selected])return toast('Approve the team configuration and generate a timeline first.');if(!current().approved)return toast('Approve the SRS baseline first.');reviews().pm=true;captureProjectVersion('timeline-result','PM approved timeline');return approveBeforeReview();};
function feedbackPanel(stage,allowed){const comments=reviews().comments[stage]||[];return '<section class="panel review-panel"><div class="panel-title"><h2>'+ (stage==='architecture'?'Engineering review':'Timeline feedback')+'</h2>'+badge(stage==='timeline-result'&&reviews().pm?'Approved':'In review')+'</div><div class="form">'+personaControl()+'<form onsubmit="addReviewComment(event,\''+stage+'\')"><label class="field">Feedback<textarea name="comment" required maxlength="4000" placeholder="Describe a concern, assumption or suggested change"></textarea></label><div class="actions"><button class="primary" '+(allowed.includes(reviewPersona)?'':'disabled')+'>Post feedback</button></div></form><p class="sub">Reviewers: '+allowed.join(', ')+'</p><div class="review-comments">'+(comments.length?comments.map(c=>'<article><strong>'+esc(c.author)+'</strong> <span class="badge gray">'+esc(c.role)+'</span><small>'+new Date(c.time).toLocaleString()+'</small><p>'+esc(c.text)+'</p></article>').join(''):'<p class="sub">No feedback yet.</p>')+'</div></div></section>';}
function addReviewComment(e,stage){e.preventDefault();const allowed=stage==='architecture'?['Senior Engineer','CTO']:['PM','Team Lead','Developer'];if(!allowed.includes(reviewPersona))return;const text=String(new FormData(e.target).get('comment')||'').trim();if(!text)return; (reviews().comments[stage] ||= []).push({author:profile.name,role:reviewPersona,text,time:new Date().toISOString()});captureProjectVersion(stage,'Feedback added');render();}
const teamPage=blueprintPageRoutes.timeline;
blueprintPageRoutes.timeline=function(){const r=reviews();return teamPage()+'<section class="panel review-panel"><div class="panel-title"><h2>Team configuration approval</h2></div><div class="form">'+personaControl()+'<div class="approval-grid"><article><strong>Client approval</strong>'+badge(r.client?'Approved':'Pending')+button('Approve as client',"approveTeamConfig('client')")+'</article><article><strong>CTO / PM approval</strong>'+badge(r.technical?'Approved':'Pending')+button('Approve as CTO / PM',"approveTeamConfig('technical')")+'</article></div><p class="sub">Changing the configuration resets both approvals and the estimated timeline.</p></div></section>';};
const resultPage=blueprintPageRoutes['timeline-result'];blueprintPageRoutes['timeline-result']=function(){return resultPage()+feedbackPanel('timeline-result',['PM','Team Lead','Developer']);};
const architectureReviewPage=blueprintPageRoutes.architecture;blueprintPageRoutes.architecture=function(){return architectureReviewPage()+feedbackPanel('architecture',['Senior Engineer','CTO']);};
document.addEventListener('change',e=>{if(e.target.matches('#timelineInputs input')){syncTeamConfig();render();}if(e.target.id==='architectureNotes'){captureProjectVersion('architecture','Architecture notes edited');}});
const meetingAfterPage=blueprintPageRoutes.meetings;blueprintPageRoutes.meetings=function(){return meetingAfterPage()+'<section class="panel review-panel"><div class="form"><h2>Next: prepare your requirements</h2><p>Review the transcript, then continue with text and supporting documents before creating the SRS.</p><div class="actions"><button class="primary" '+(demoRecordingActive||!demoRecordingCount?'disabled':'')+' onclick="useCompletedRecording()">Continue to requirement request →</button></div></div></section>';};
function useCompletedRecording(){if(!selected)return toast('Select a project first.');if(demoRecordingActive)return toast('Stop the recording first.');const d=requestDraft();d.entries=jpMeeting.slice(0,demoRecordingCount).map(r=>[...r]);d.title=demoRecordingTitle;d.tab='meeting';d.meetingType='recording';captureProjectVersion('meetings','Recording added to project context');navigate('request');}
blueprintPageRoutes.workspaces=function(){return bpHeading('Workspaces','Manage your workspace, people, teams and projects.',button('+ New workspace',"openCreate('workspace')",true))+'<div class="cards">'+spaces.map(w=>'<section class="card"><span class="tile-icon">'+icon('workspaces')+'</span><h2>'+esc(w.name)+'</h2><p>'+esc(w.desc)+'</p>'+badge(w.id===workspace?'Current workspace':'Workspace')+'<div class="workspace-counts"><span>'+projects.filter(p=>p.space===w.id).length+' projects</span><span>'+teams.filter(t=>t.space===w.id).length+' teams</span><span>'+users.filter(u=>u.space===w.id).length+' members</span></div><div class="workspace-links">'+button('Open workspace','switchWorkspace('+w.id+')')+button('Settings & members',"manageEntity('workspace',"+w.id+")")+button('Projects',"workspaceDestination("+w.id+",'projects')")+button('Teams',"workspaceDestination("+w.id+",'teams')")+button('Users & invitations',"workspaceDestination("+w.id+",'users')")+'</div></section>').join('')+'</div>';};
function workspaceDestination(id,route){switchWorkspace(id);navigate(route);}
for(const route of ['requirements','stories','timeline-result','architecture','tests']){const page=blueprintPageRoutes[route];blueprintPageRoutes[route]=function(){const html=page();if(!selected)return html;captureProjectVersion(route);const t=document.createElement('template');t.innerHTML=html;const h=t.content.querySelector('.page-head');if(h){let a=h.querySelector('.actions');if(!a){a=document.createElement('div');a.className='actions';h.append(a);}a.insertAdjacentHTML('afterbegin',button('Version history',"showProjectHistory('"+route+"')"));}return t.innerHTML;};}
Object.assign(localizedLabels,{'Preview as':'プレビューの役割','Team configuration approval':'チーム構成の承認','Client approval':'クライアント承認','CTO / PM approval':'CTO / PM承認','Approve as client':'クライアントとして承認','Approve as CTO / PM':'CTO / PMとして承認','Engineering review':'エンジニアレビュー','Timeline feedback':'スケジュールへのフィードバック','Feedback':'フィードバック','Post feedback':'フィードバックを投稿','No feedback yet.':'フィードバックはまだありません。','Next: prepare your requirements':'次のステップ：要件を準備','Continue to requirement request →':'要件リクエストへ進む →','Settings & members':'設定とメンバー','Open workspace':'ワークスペースを開く','Users & invitations':'ユーザーと招待','Requirement links':'要件の関連'});
render();
// Compact timeline decisions and a shared feedback log.
function timelineDecisions(){return reviews().decisions ||= {configuration:'Pending',estimate:'Pending',feedback:[]};}
const syncConfigBeforeDecisions=syncTeamConfig;
syncTeamConfig=function(){const previous=reviews().configKey,ok=syncConfigBeforeDecisions();if(ok&&previous!==reviews().configKey){const d=timelineDecisions();d.configuration='Pending';d.estimate='Pending';}return ok;};
function approveTimelineStage(stage){if(stage==='configuration'&&!syncTeamConfig())return;if(stage==='estimate'&&!generatedTimelines[selected])return toast('Generate a timeline first.');const d=timelineDecisions();d[stage]='Approved';if(stage==='configuration'){reviews().client=true;reviews().technical=true;}else{reviews().pm=true;backlog().approved=true;}captureProjectVersion('timeline-result',stage+' approved');render();}
function disapproveTimelineStage(stage){if(stage==='configuration'&&!syncTeamConfig())return;const box=document.getElementById('modal');box.className='history-dialog';box.innerHTML='<form onsubmit="submitTimelineDisapproval(event,\''+stage+'\')"><div class="history-heading"><h2>Disapprove</h2><button type="button" aria-label="Close" onclick="document.getElementById(\'modal\').close()">×</button></div><div class="form"><label class="field">Feedback<textarea name="feedback" required maxlength="4000" placeholder="Explain what should be changed before approval"></textarea></label><p class="sub">This feedback will appear on both timeline pages.</p></div><div class="history-footer"><button type="button" onclick="document.getElementById(\'modal\').close()">Cancel</button><button class="request-stop" type="submit">Disapprove</button></div></form>';box.showModal();box.querySelector('textarea').focus();}
function submitTimelineDisapproval(e,stage){e.preventDefault();const text=String(new FormData(e.target).get('feedback')||'').trim();if(!text)return;const d=timelineDecisions();d[stage]='Disapproved';d.feedback.push({stage,text,author:profile.name,time:new Date().toISOString()});reviews().pm=false;backlog().approved=false;if(stage==='configuration'){reviews().client=false;reviews().technical=false;d.estimate='Pending';}captureProjectVersion('timeline-result',stage+' disapproved');document.getElementById('modal').close();render();}
generateTimelineResult=function(){if(!syncTeamConfig())return;if(timelineDecisions().configuration!=='Approved')return toast('Approve the team configuration before generating the timeline.');timelineDecisions().estimate='Pending';reviews().pm=false;return generateBeforeReview();};
approveDeliveryPlan=function(){if(!generatedTimelines[selected])return toast('Generate a timeline first.');if(timelineDecisions().estimate!=='Approved')return toast('Approve the estimated timeline first.');backlog().approved=true;reviews().pm=true;track('Approved timeline continued to architecture','Planning');navigate('architecture');};
function sharedTimelineFeedback(){const list=timelineDecisions().feedback;return '<section class="panel review-panel"><div class="panel-title"><h2>Review feedback</h2><span class="badge gray">'+list.length+'</span></div><div class="form review-comments">'+(list.length?list.slice().reverse().map(c=>'<article><span class="badge gray">'+(c.stage==='configuration'?'Team configuration':'Estimated timeline')+'</span><p><strong>'+esc(c.author)+'</strong> · '+new Date(c.time).toLocaleString()+'</p><p>'+esc(c.text)+'</p></article>').join(''):'<p class="sub">No feedback yet.</p>')+'</div></section>';}
for(const [route,stage] of [['timeline','configuration'],['timeline-result','estimate']]){const base=blueprintPageRoutes[route];blueprintPageRoutes[route]=function(){const t=document.createElement('template');t.innerHTML=base();t.content.querySelectorAll('.review-panel').forEach(e=>e.remove());t.content.querySelectorAll('button[onclick="approveDeliveryPlan()"]').forEach(e=>e.remove());const h=t.content.querySelector('.page-head');if(h){let a=h.querySelector('.actions');if(!a){a=document.createElement('div');a.className='actions';h.append(a);}const disabled=stage==='estimate'&&!generatedTimelines[selected];a.insertAdjacentHTML('beforeend',badge(timelineDecisions()[stage])+'<button class="request-stop" '+(disabled?'disabled':'')+' onclick="disapproveTimelineStage(\''+stage+'\')">Disapprove</button><button class="primary" '+(disabled?'disabled':'')+' onclick="approveTimelineStage(\''+stage+'\')">Approve</button>');if(stage==='estimate'&&timelineDecisions().estimate==='Approved')a.insertAdjacentHTML('beforeend',button('Continue to architecture →','approveDeliveryPlan()',true));}return t.innerHTML+sharedTimelineFeedback();};}
Object.assign(localizedLabels,{'Disapprove':'承認しない','Review feedback':'レビューのフィードバック','This feedback will appear on both timeline pages.':'このフィードバックは両方のスケジュールページに表示されます。','Explain what should be changed before approval':'承認前に必要な変更を入力してください','Disapproved':'差し戻し','Continue to architecture →':'アーキテクチャへ進む →'});
render();
// Configuration collects inputs; approval belongs to the generated estimate.
const timelinePrompts={},timelineGenerationContexts={};
function updateTimelinePrompt(value){if(timelinePrompts[selected]===value)return;timelinePrompts[selected]=value;timelineDecisions().estimate='Pending';reviews().pm=false;backlog().approved=false;}
blueprintPageRoutes.timeline=function(){const t=document.createElement('template');t.innerHTML=teamPage();const form=t.content.querySelector('#timelineInputs')?.parentElement;if(form)form.insertAdjacentHTML('beforeend','<label class="field timeline-prompt">Additional instructions for AI (optional)<textarea id="timelinePrompt" oninput="updateTimelinePrompt(this.value)" placeholder="For example: prioritize the MVP, allow time for client review, and avoid deployments on Fridays.">'+esc(timelinePrompts[selected]||'')+'</textarea></label><p class="sub">Included with your requirements and team configuration when preparing the timeline. This demo saves the prompt; AI estimation is not connected.</p>');return t.innerHTML;};
generateTimelineResult=function(){if(!syncTeamConfig())return;const prompt=document.getElementById('timelinePrompt')?.value||timelinePrompts[selected]||'';timelinePrompts[selected]=prompt;timelineGenerationContexts[selected]={prompt,configuration:JSON.parse(JSON.stringify(timelineState())),requirements:JSON.parse(JSON.stringify(backlog().rows)),createdAt:new Date().toISOString()};timelineDecisions().estimate='Pending';reviews().pm=false;return generateBeforeReview();};
const estimateWithPrompt=blueprintPageRoutes['timeline-result'];
blueprintPageRoutes['timeline-result']=function(){let html=estimateWithPrompt();const ctx=timelineGenerationContexts[selected];if(ctx?.prompt){html+='<section class="panel review-panel"><div class="panel-title"><h2>Generation instructions</h2></div><div class="form"><p style="white-space:pre-wrap">'+esc(ctx.prompt)+'</p><p class="sub">Saved with this estimate. Prompt-based AI analysis is not connected in this demo.</p></div></section>';}return html;};
const snapshotBeforePrompt=reviewSnapshot;reviewSnapshot=function(route){const data=JSON.parse(snapshotBeforePrompt(route));data.timelineGenerationContext=timelineGenerationContexts[selected]||null;return JSON.stringify(data);};
Object.assign(localizedLabels,{'Additional instructions for AI (optional)':'AIへの追加指示（任意）','Generation instructions':'生成時の指示','For example: prioritize the MVP, allow time for client review, and avoid deployments on Fridays.':'例：MVPを優先し、クライアントレビューの時間を確保して、金曜日のリリースを避けてください。','Included with your requirements and team configuration when preparing the timeline. This demo saves the prompt; AI estimation is not connected.':'スケジュール作成時に要件とチーム構成とともに含めます。このデモは指示を保存しますが、AI見積もりには未接続です。','Saved with this estimate. Prompt-based AI analysis is not connected in this demo.':'この見積もりとともに保存されています。このデモでは指示に基づくAI分析は未接続です。'});
render();
